import{_ as t,o as a,c as r,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const I=JSON.parse('{"title":"Arming Ceph- CI Enhancement and UADK Integration - Rongqi Sun, HUAWEI TECHNOLOGIES CO., LTD.","description":"","frontmatter":{"title":"Arming Ceph- CI Enhancement and UADK Integration - Rongqi Sun, HUAWEI TECHNOLOGIES CO., LTD.","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","ARM架构","CI增强","UADK集成","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Arming_Ceph_-_CI_Enhancement_and_UADK_Integration_-_Rongqi_Sun_HUAWEI_TECHNOLOGIES_CO._LTD..md","filePath":"posts/2025/Arming_Ceph_-_CI_Enhancement_and_UADK_Integration_-_Rongqi_Sun_HUAWEI_TECHNOLOGIES_CO._LTD..md","lastUpdated":1780459816000}'),i={name:"posts/2025/Arming_Ceph_-_CI_Enhancement_and_UADK_Integration_-_Rongqi_Sun_HUAWEI_TECHNOLOGIES_CO._LTD..md"};function o(l,n,s,_,C,g){return a(),r("div",null,[...n[0]||(n[0]=[e('<h3 id="会议纪要-ceph社区关于arm架构的ci增强与uadk集成讨论" tabindex="-1">会议纪要：Ceph社区关于ARM架构的CI增强与UADK集成讨论 <a class="header-anchor" href="#会议纪要-ceph社区关于arm架构的ci增强与uadk集成讨论" aria-label="Permalink to &quot;会议纪要：Ceph社区关于ARM架构的CI增强与UADK集成讨论&quot;">​</a></h3><p><strong>会议时间</strong>：不详<br><strong>主讲人</strong>：Rongqi Sun，华为<br><strong>参会人员</strong>：Ceph社区成员</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><ul><li>Ceph在ARM架构上的CI增强与UADK集成。</li></ul><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>MCI（Make Check I/O）改进</strong><ul><li><strong>背景</strong>：ARM架构在移动、嵌入式市场和服务器领域日益重要。</li><li><strong>挑战</strong>：MCI管道存在不稳定问题，包括单元测试失败、依赖项不匹配和不同Ubuntu版本导致的手动修改。</li><li><strong>解决方案</strong>：清理遗留代码，统一操作系统版本，并在OpenEuler上进行构建。捕获构建工件并进行并行化以加速运行速度，解决超过20个相关问题。</li><li><strong>成果</strong>：MCI现在要求在代码合并前必须通过测试。</li></ul></li><li><strong>Crimson存储检测器问题</strong><ul><li><strong>问题</strong>：Crimson存储检测器在ARM上随机失败，难以重现。</li><li><strong>解决方案</strong>：关闭Crimson存储检测器，等待Ceph子模块迁移到librados后重新开放。</li></ul></li><li><strong>未来工作</strong><ul><li><strong>MCI优化</strong>：提议将部分单元测试从MCI移至其他CI工具，以缩短运行时间。</li><li><strong>ARM CI通道</strong>：计划构建ARM CI通道，吸引更多ARM爱好者参与。</li><li><strong>回溯支持</strong>：将MCI检查引入backport分支。</li><li><strong>更多开源操作系统支持</strong>：增加对更多开源操作系统的支持。</li></ul></li><li><strong>EDK集成</strong><ul><li><strong>背景</strong>：EDK是用户空间加速开发工具包，支持加密和压缩加速。</li><li><strong>进展</strong>：在Ceph代码中添加了UDK与UKPI的对比类，并已合并到main分支。通过RGW和RBD的测试，EDK显著减少了CPU使用率。</li><li><strong>未来计划</strong>：支持OpenCell3的provider接口，讨论ChaCha20模式的加速支持。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续优化MCI，缩短运行时间。</li><li>构建ARM CI通道，吸引更多ARM爱好者参与。</li><li>支持更多开源操作系统。</li><li>进一步讨论EDK与OpenCell3的集成，特别是ChaCha20模式的加速支持。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>MCI优化</strong>：与Pat讨论将部分单元测试移至其他CI工具。</li><li><strong>ARM CI通道</strong>：构建ARM CI通道，吸引更多ARM爱好者参与。</li><li><strong>EDK集成</strong>：与Ric进一步讨论ChaCha20模式的加速支持。</li></ul><h4 id="其他" tabindex="-1">其他： <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他：&quot;">​</a></h4><ul><li>主讲人鼓励社区成员参与ARM相关的工作，提升Ceph在ARM架构上的性能。</li></ul><p><strong>会议总结</strong>：<br> 本次会议讨论了Ceph在ARM架构上的改进，特别是MCI的优化和EDK的集成。通过清理遗留代码、统一操作系统版本等措施，MCI的稳定性得到了显著提升。未来将继续优化MCI，缩短运行时间，并构建ARM CI通道以吸引更多ARM爱好者参与。此外，EDK的集成显著提升了加密和压缩的性能，未来将进一步讨论与OpenCell3的集成，特别是ChaCha20模式的加速支持。</p>',13)])])}const u=t(i,[["render",o]]);export{I as __pageData,u as default};
